type ScoreEntry = {
  name: string
  score: number
  accuracy: number
}

function sortScores(entries: Array<ScoreEntry>) {
  return entries.toSorted((left, right) => right.score - left.score)
}

function pickBest<T extends { score: number }>(items: Array<T>) {
  const sorted = items.toSorted((left, right) => right.score - left.score)

  if (sorted.length === 0) {
    return null
  }

  return sorted[0]
}

interface RouteSearch {
  language?: 'javascript' | 'typescript' | 'python' | 'go'
  sound?: 'on' | 'off'
}

function getRouteLanguage(search: RouteSearch) {
  return search.language ?? 'javascript'
}

export function assertNever(value: never): never {
  throw new Error(`Unexpected value: ${value}`)
}

export function formatScore(value: number) {
  return `${value.toFixed(0)} cpm`
}

function normalizeValues(values: Array<string | undefined>) {
  return values
    .filter(Boolean)
    .map((value) => value.trim())
    .filter((value) => value.length > 0)
}

const normalized = normalizeValues([' go ', undefined, ' rust '])

type Result<T, E = Error> =
  | { ok: true; value: T }
  | { ok: false; error: E }

function tryParseJson<T>(raw: string): Result<T> {
  try {
    return { ok: true, value: JSON.parse(raw) as T }
  } catch (error) {
    return { ok: false, error: error as Error }
  }
}

type Action =
  | { kind: 'increment'; by: number }
  | { kind: 'reset' }
  | { kind: 'set'; value: number }

function reduce(state: number, action: Action): number {
  switch (action.kind) {
    case 'increment': return state + action.by
    case 'reset': return 0
    case 'set': return action.value
  }
}

function memoize<Args extends Array<unknown>, R>(fn: (...args: Args) => R) {
  const cache = new Map<string, R>()

  return (...args: Args): R => {
    const key = JSON.stringify(args)

    if (!cache.has(key)) {
      cache.set(key, fn(...args))
    }

    return cache.get(key) as R
  }
}

function pluck<T, K extends keyof T>(items: ReadonlyArray<T>, key: K): Array<T[K]> {
  return items.map((item) => item[key])
}

const names = pluck([{ id: 1, name: 'Ada' }, { id: 2, name: 'Linus' }], 'name')

const HttpStatus = {
  Ok: 200,
  Created: 201,
  BadRequest: 400,
  Unauthorized: 401,
  NotFound: 404,
  ServerError: 500,
} as const

type HttpStatus = (typeof HttpStatus)[keyof typeof HttpStatus]

function isError(status: HttpStatus) {
  return status >= 400
}
